        powerup.active = false;
        continue;
      }
      if (harmless) continue;
      if (!circleHit(powerup.x, powerup.y, powerup.radius, wisp.x, wisp.y, wisp.radius)) continue;
      powerup.active = false;
      if (powerup.kind === KIND_NOVA) {
