        events |= EVENT_SHIELD;
      }
    }

    // Sparks fade and drift.
    for (const spark of sparks) {
      if (!spark.active) continue;
      spark.life -= dt;
      if (spark.life <= 0) {
        spark.active = false;
        continue;
      }
      spark.x += spark.vx * dt;
      spark.y += spark.vy * dt;
      spark.vx *= 0.985;
      spark.vy *= 0.985;
    }

    return events;
  }

  reset();
  return { state, reset, step, comboMultiplier, spawnSparks };
