    drawHud(state, palette);
    if (screen === SCREEN_PAUSED) drawPanel('Paused', PAUSED_LINES, 'Press P to resume', palette);
    else if (screen === SCREEN_OVER) {
      OVER_LINES[0] = finalLabel(state.score);
